        id: "seg-p4-98-07",
        speaker: "Speaker",
        start_time: 77.38,
        end_time: 89.61,
        text_en: "So, we need to revise the design as quickly as possible.",
        text_vi: "Vì vậy, chúng ta cần sửa đổi thiết kế càng nhanh càng tốt.",
